operation.add:
// ProBG Blog
$this->load->language('extension/module/probg_blog');
$probg_blog = array();
if ($this->user->hasPermission('access', 'extension/probg_blog/article')) {
    $probg_blog[] = array('name' => $this->language->get('text_menu_articles'), 'href' => $this->url->link('extension/probg_blog/article', 'user_token=' . $this->session->data['user_token'], true), 'children' => array());
}
if ($this->user->hasPermission('access', 'extension/probg_blog/category')) {
    $probg_blog[] = array('name' => $this->language->get('text_menu_categories'), 'href' => $this->url->link('extension/probg_blog/category', 'user_token=' . $this->session->data['user_token'], true), 'children' => array());
}
if ($this->user->hasPermission('access', 'extension/module/probg_blog')) {
    $probg_blog[] = array('name' => $this->language->get('text_menu_settings'), 'href' => $this->url->link('extension/module/probg_blog', 'user_token=' . $this->session->data['user_token'], true), 'children' => array());
}
if ($probg_blog) $data['menus'][] = array('id' => 'menu-probg-blog', 'icon' => 'fa-newspaper-o', 'name' => $this->language->get('text_menu_blog'), 'href' => '', 'children' => $probg_blog);

if (isset($data['route']) && $data['route'] == 'extension/module/probg_blog' && ($key == 'route' || $key == 'probg_blog_category_id' || $key == 'probg_blog_article_id')) {
    $probg_blog_query = ($key == 'route') ? $value : $key . '=' . (int)$value;
    $probg_blog_seo = $this->db->query("SELECT * FROM " . DB_PREFIX . "seo_url WHERE `query` = '" . $this->db->escape($probg_blog_query) . "' AND store_id = '" . (int)$this->config->get('config_store_id') . "' AND language_id = '" . (int)$this->config->get('config_language_id') . "'");
    if ($probg_blog_seo->num_rows && $probg_blog_seo->row['keyword']) {
        $url .= '/' . $probg_blog_seo->row['keyword'];
        if ($key != 'route') {
            unset($data[$key]);
        }
    }
}

if (isset($this->request->get['probg_blog_category_id']) || isset($this->request->get['probg_blog_article_id'])) {
    $probg_blog_layout_table = $this->db->query("SHOW TABLES LIKE '" . $this->db->escape(DB_PREFIX . "probg_blog_category_to_layout") . "'");
    if ($probg_blog_layout_table->num_rows && isset($this->request->get['probg_blog_category_id'])) {
        $probg_blog_layout = $this->db->query("SELECT layout_id FROM " . DB_PREFIX . "probg_blog_category_to_layout WHERE category_id = '" . (int)$this->request->get['probg_blog_category_id'] . "' AND store_id = '" . (int)$this->config->get('config_store_id') . "'");
        if ($probg_blog_layout->num_rows && (int)$probg_blog_layout->row['layout_id']) {
            return (int)$probg_blog_layout->row['layout_id'];
        }
    } elseif ($probg_blog_layout_table->num_rows && isset($this->request->get['probg_blog_article_id'])) {
        $probg_blog_layout = $this->db->query("SELECT c2l.layout_id FROM " . DB_PREFIX . "probg_blog_article a INNER JOIN " . DB_PREFIX . "probg_blog_category_to_layout c2l ON(c2l.category_id = a.category_id) WHERE a.article_id = '" . (int)$this->request->get['probg_blog_article_id'] . "' AND c2l.store_id = '" . (int)$this->config->get('config_store_id') . "'");
        if ($probg_blog_layout->num_rows && (int)$probg_blog_layout->row['layout_id']) {
            return (int)$probg_blog_layout->row['layout_id'];
        }
    }
}

$category_id = isset($this->request->get['probg_blog_category_id']) ? (int)$this->request->get['probg_blog_category_id'] : 0;
$article_id = isset($this->request->get['probg_blog_article_id']) ? (int)$this->request->get['probg_blog_article_id'] : 0;
$route = isset($this->request->get['route']) ? (string)$this->request->get['route'] : '';
$is_blog_page = ($route === 'extension/module/probg_blog' || $category_id || $article_id);

// OpenCart can invoke a non-instance module from a layout without passing
// a $setting array. On non-blog routes that call must render only the
// configured layout block, never the full blog page.
if (!$is_blog_page || $this->config->get('probg_blog_page_rendering')) {
    return $this->module(is_array($setting) ? $setting : array());
}

// Prevent recursive full-page rendering when ProBG Blog is also assigned
// to a layout used by the blog section itself.
$this->config->set('probg_blog_page_rendering', 1);
